<script setup lang="ts">
import { ref } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import { adminDelete, adminGet, adminPost, adminPut } from "../../../admin/api/adminClient";

type Member={userId:number;username:string;displayName:string};type Team={id:number;name:string;memberCount:number;members:Member[]};type User={id:number;username:string;displayName:string};type Page<T>={list:T[];total:number};
const teams=ref<Team[]>([]);const loading=ref(false);const createDialog=ref(false);const renameDialog=ref(false);const memberDialog=ref(false);const createName=ref("");const renameName=ref("");const renameTarget=ref<Team|null>(null);const memberTarget=ref<Team|null>(null);const keyword=ref("");const candidates=ref<User[]>([]);const searching=ref(false);const saving=ref(false);const addingId=ref<number|null>(null);
async function load(){loading.value=true;try{teams.value=await adminGet<Team[]>("/api/admin/v1/teams");}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"队伍列表加载失败");}finally{loading.value=false;}}
async function create(){if(!createName.value.trim()){ElMessage.warning("队伍名称不能为空");return;}saving.value=true;try{await adminPost("/api/admin/v1/teams",{name:createName.value.trim()});ElMessage.success("队伍已创建");createDialog.value=false;createName.value="";await load();}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"创建失败");}finally{saving.value=false;}}
function openRename(team:Team){renameTarget.value=team;renameName.value=team.name;renameDialog.value=true;}
async function rename(){if(!renameTarget.value||!renameName.value.trim()){ElMessage.warning("队伍名称不能为空");return;}saving.value=true;try{await adminPut(`/api/admin/v1/teams/${renameTarget.value.id}`,{name:renameName.value.trim()});ElMessage.success("队伍名称已更新");renameDialog.value=false;await load();}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"修改失败");}finally{saving.value=false;}}
async function searchUsers(value:string){keyword.value=value;if(!value.trim()){candidates.value=[];return;}searching.value=true;try{const result=await adminGet<Page<User>>(`/api/admin/v1/users?page=1&pageSize=20&keyword=${encodeURIComponent(value.trim())}`);candidates.value=result.list??[];}catch{candidates.value=[];}finally{searching.value=false;}}
function openMembers(team:Team){memberTarget.value=team;keyword.value="";candidates.value=[];memberDialog.value=true;}
async function addMember(user:User){if(!memberTarget.value)return;addingId.value=user.id;try{await adminPost(`/api/admin/v1/teams/${memberTarget.value.id}/members`,{userId:user.id});ElMessage.success("成员已添加");await load();memberTarget.value=teams.value.find(item=>item.id===memberTarget.value?.id)??memberTarget.value;candidates.value=candidates.value.filter(item=>item.id!==user.id);}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"添加失败");}finally{addingId.value=null;}}
async function removeMember(member:Member){if(!memberTarget.value)return;try{await ElMessageBox.confirm(`从 ${memberTarget.value.name} 移除 ${member.displayName||member.username}？`,"移除成员",{type:"warning"});await adminDelete(`/api/admin/v1/teams/${memberTarget.value.id}/members/${member.userId}`);ElMessage.success("成员已移除");await load();memberTarget.value=teams.value.find(item=>item.id===memberTarget.value?.id)??memberTarget.value;}catch(cause){if(cause!=="cancel"&&cause!=="close")ElMessage.error(cause instanceof Error?cause.message:"移除失败");}}
void load();
</script>

<template><section class="team-page page-container"><el-card shadow="never"><template #header><div class="management-card-heading"><div class="management-card-actions"><header class="page-heading"><div class="actions"><el-button type="primary" @click="createName='';createDialog=true">新建队伍</el-button></div></header></div></div></template><el-skeleton v-if="loading&&!teams.length" :rows="6" animated/><template v-else><el-card v-for="team in teams" :key="team.id" shadow="never"><template #header><div class="team-header"><strong>{{team.name}}（{{team.memberCount}} 名成员）</strong><div><el-button @click="openRename(team)">改名字</el-button><el-button type="primary" @click="openMembers(team)">添加成员</el-button></div></div></template><div v-if="team.members?.length" class="members"><el-tag v-for="member in team.members" :key="member.userId" closable @close="removeMember(member)">{{member.displayName||member.username}}</el-tag></div><el-empty v-else description="暂无成员，点击添加成员" :image-size="64"/></el-card><el-empty v-if="!teams.length" description="暂无队伍"/></template>
  </el-card>
<el-dialog class="qoj-management-dialog" v-model="createDialog" title="新建队伍" width="440px"><el-input v-model="createName" maxlength="100" placeholder="输入队伍名称" @keyup.enter="create"/><template #footer><el-button @click="createDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">创建</el-button></template></el-dialog>
  <el-dialog class="qoj-management-dialog" v-model="renameDialog" title="修改队伍名称" width="440px"><el-input v-model="renameName" maxlength="100" placeholder="输入队伍名称" @keyup.enter="rename"/><template #footer><el-button @click="renameDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="rename">保存</el-button></template></el-dialog>
  <el-dialog class="qoj-management-dialog" v-model="memberDialog" :title="`添加成员${memberTarget?` - ${memberTarget.name}`:''}`" width="560px"><el-input v-model="keyword" clearable placeholder="用户名 / 姓名 / 学号 / 邮箱" @input="searchUsers"/><el-skeleton v-if="searching" :rows="3" animated/><el-empty v-else-if="!candidates.length" :description="keyword.trim()?'未找到匹配用户':'输入关键字搜索用户'"/><div v-else class="candidate-list"><div v-for="user in candidates" :key="user.id" class="candidate"><span>{{user.displayName||user.username}} <small>@{{user.username}}</small></span><el-button size="small" type="primary" :disabled="memberTarget?.members?.some(item=>item.userId===user.id)" :loading="addingId===user.id" @click="addMember(user)">{{memberTarget?.members?.some(item=>item.userId===user.id)?'已加入':'添加'}}</el-button></div></div><template #footer><el-button @click="memberDialog=false">完成</el-button></template></el-dialog>
</section></template>

<style scoped>.team-page{display:flex;flex-direction:column;gap:16px}.page-heading,.actions,.team-header{display:flex;align-items:center;justify-content:space-between;gap:10px}.page-heading h1{margin:0;font-size:22px}.page-heading p{margin:6px 0 0;color:var(--el-text-color-secondary);font-size:13px}.team-header>div{display:flex;gap:8px}.members{display:flex;flex-wrap:wrap;gap:8px}.candidate-list{max-height:330px;overflow:auto;margin-top:12px}.candidate{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 2px;border-bottom:1px solid #ebeef5}.candidate small{margin-left:8px;color:var(--el-text-color-placeholder)}@media(max-width:600px){.page-heading,.team-header{align-items:flex-start;flex-direction:column}}</style>
